package govflow

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
)

// 本文件是状态文件中“必填标量字段”的统一读取与判定。
//
// 逐票明细（representative/weight/support/voted_at）、首次计票结果
// （for_weight/against_weight）与执行凭据（executed_at/order、逐笔动作的
// index）遵循同一条字段规则：字段必须明确写出、不得为 null、JSON 类型必须与
// 声明一致（整数另要求 int64 范围内的整数字面量，小数/指数/超界同样拒绝）。
// 缺失或 null 绝不补成零值：明确写出的 false 是有效反对票，窗口允许时明确
// 写出的 0 是有效时间、权重或顺序编号。
//
// 各类记录共用这里的判定，又各自把字段名与原因短语格式化为带业务位置
// （提案编号、票据下标、计票记录标识）的错误，不会退化成没有记录位置的
// 通用错误。

// scalarKind 是必填标量字段期望的 JSON 类型；其字符串形式与错误信息中
// “want %s”的用词逐字一致。
type scalarKind string

const (
	scalarString  scalarKind = "string"
	scalarBoolean scalarKind = "boolean"
	scalarInteger scalarKind = "integer" // int64 范围内的整数字面量
)

// rawField 把一个必填标量字段的字段名、期望类型与解码时接住的原始 JSON
// 放在一起，供 validateRawFields 按声明顺序逐字段判定。
type rawField struct {
	name string
	kind scalarKind
	raw  json.RawMessage
}

// validateRawFields 按声明顺序判定各必填字段，返回第一个不合要求字段的错误；
// 字段全部合法时返回 nil。locate 把字段名与原因短语格式化为带业务位置的错误，
// 判定顺序因此完全由 fields 的声明顺序决定，与记录类型无关。
func validateRawFields(fields []rawField, locate func(field, problem string) error) error {
	for _, f := range fields {
		if problem := requiredScalarProblem(f.raw, f.kind); problem != "" {
			return locate(f.name, problem)
		}
	}
	return nil
}

// requiredScalarProblem 统一判定一个必填标量字段的原始 JSON：
// 字段未写出、显式为 null 或 JSON 类型不符都返回具体原因短语；
// 合法（含明确写出的 false 与 0）返回空串。
func requiredScalarProblem(raw json.RawMessage, kind scalarKind) string {
	switch {
	case raw == nil:
		return "is missing"
	case string(raw) == "null":
		return "is null"
	case !scalarTypeMatches(raw, kind):
		return fmt.Sprintf("has wrong type: want %s, got %s", kind, jsonValueType(raw))
	}
	return ""
}

// scalarTypeMatches 判定原始 JSON 是否确实是期望类型的值。
func scalarTypeMatches(raw json.RawMessage, kind scalarKind) bool {
	switch kind {
	case scalarString:
		return jsonValueType(raw) == "string"
	case scalarBoolean:
		return jsonValueType(raw) == "boolean"
	case scalarInteger:
		return isInt64Number(raw)
	}
	return false
}

// fillString 仅在原始 JSON 确实是字符串时把值解进 dst；否则 dst 保持零值，
// 类型不符留待校验拒绝，绝不能让错误类型悄悄落成零值并参与查询或计票。
func fillString(raw json.RawMessage, dst *string) {
	if jsonValueType(raw) == "string" {
		_ = json.Unmarshal(raw, dst)
	}
}

// fillBool 与 fillString 同理，目标类型为布尔值。
func fillBool(raw json.RawMessage, dst *bool) {
	if jsonValueType(raw) == "boolean" {
		_ = json.Unmarshal(raw, dst)
	}
}

// fillInt64 与 fillString 同理，目标类型为 int64 整数。
func fillInt64(raw json.RawMessage, dst *int64) {
	if isInt64Number(raw) {
		_ = json.Unmarshal(raw, dst)
	}
}

// jsonValueType 按字段实际写出 JSON 的首字节归类其 JSON 类型。
// RawMessage 是从合法 JSON 文档中取出的单个值，首字节足以区分
// 字符串/布尔/null/数字/数组/对象，无需再次解码。
func jsonValueType(raw json.RawMessage) string {
	for _, c := range raw {
		switch c {
		case ' ', '\t', '\n', '\r':
			continue
		case '"':
			return "string"
		case 't', 'f':
			return "boolean"
		case 'n':
			return "null"
		case '[':
			return "array"
		case '{':
			return "object"
		default:
			return "number"
		}
	}
	return "invalid json"
}

// isInt64Number 判断原始 JSON 是否为落在有符号 64 位整数范围内的整数字面量：
// 必须是 JSON 数字（首字节为数字或 '-'），且能被 ParseInt 以 10 进制精确解析。
// 小数、指数、超界整数均返回 false。
func isInt64Number(raw json.RawMessage) bool {
	if jsonValueType(raw) != "number" {
		return false
	}
	_, err := strconv.ParseInt(strings.TrimSpace(string(raw)), 10, 64)
	return err == nil
}

package govflow

import (
	"fmt"
	"unicode/utf8"
)

// 本文件在状态文件交给 encoding/json 之前逐字节扫描其中的每一个 JSON
// 字符串（对象键与字段值同等适用），保证读取路径拿到的文本可信：
//
//   - 字符串中出现非法 UTF-8 字节序列（残缺的多字节序列、续字节缺失、
//     越界编码、WTF-8 形式写出的代理码位等）一律判整份文件损坏；
//   - \u Unicode 转义中的高代理项（U+D800–U+DBFF）与低代理项
//     （U+DC00–U+DFFF）必须按“高后立即低”的次序组成一对：
//     孤立高代理、孤立低代理、高代理后没有紧跟合法低代理转义都判损坏。
//
// encoding/json 默认把这两类内容悄悄改写成替换字符 U+FFFD 且不报错：
// 一旦账户名、提案编号、成员编号或动作原文被改写，余额与凭据仍可能重放
// 一致，查询却展示出另一个名字。扫描先于解码执行，被改写的字符串因此
// 不可能参与编号匹配、重复键判断或凭据重放——坏字符串即使出现在本次
// 没有查询的另一项提案中，整份文件也会被拒绝。
//
// 合法内容不被误伤：
//   - 中文、表情等一切合法 UTF-8 文本照常读取（包括用户明确写出的
//     U+FFFD 本身：无论直接写出 EF BF BD 还是用 `\uFFFD` 转义，都是合法
//     字符，不能仅凭读取结果含有它就认定损坏）；
//   - 一对合法的高、低代理项转义（如 😀）照常按其表示的字符
//     读取，与直接写出该字符等价，不影响编号匹配与重复键判断；
//   - 反斜杠自身被转义后出现的 “\uD800” 字样（源码拼写 "\\uD800"）是
//     普通文本：第一个反斜杠配对第二个反斜杠，uD800 只是字面字符，
//     不参与代理项配对。
//
// 报错区分两类原因，并给出从文件开头按零计数的字节位置；未配对转义的
// 位置指向该转义开始的反斜杠。这里只报告字符层面的问题，不替代字段
// 校验、投票规则与凭据重放：字符合法绝不宽免其它损坏原因。

// checkStrictStrings 逐字节扫描整份 JSON 文档中的字符串内容。
// 发现非法 UTF-8 或未配对代理项转义时返回带原因与字节偏移的错误；
// 文档存在其它语法问题时不保证在此报错（交给后续结构扫描与解码器）。
func checkStrictStrings(raw []byte) error {
	n := len(raw)
	for i := 0; i < n; {
		if raw[i] != '"' {
			i++
			continue
		}
		// 进入一个 JSON 字符串（对象键或值），content 指向开头引号。
		i++ // 越过开头引号
		for i < n {
			c := raw[i]
			if c == '"' {
				i++ // 越过结尾引号
				break
			}
			if c == '\\' {
				bs := i // 转义起始反斜杠；代理项报错位置指向这里
				i++
				if i >= n {
					break // 反斜杠后即文件结尾：未终止字符串，交给解码器拒绝
				}
				if raw[i] != 'u' {
					// 单字符转义（" \ / b f n r t）原样跳过；
					// 非法转义字符不在字符校验范围内，由解码器报告。
					// 特别地，"\\uD800" 中第一个反斜杠与第二个反斜杠配对，
					// 随后的 uD800 只是普通文本，不需要代理项配对。
					i++
					continue
				}
				cp, ok := hexEscape4(raw, i+1) // i 指向 'u'，其后是 4 个十六进制位
				if !ok {
					// \u 后不足 4 个十六进制位是 JSON 语法错误，交给解码器；
					// 不把它解释成半个代理项，跳过 'u' 继续扫描其余内容。
					i++
					continue
				}
				switch {
				case cp >= 0xD800 && cp <= 0xDBFF:
					// 高代理项：必须立即紧跟一个低代理项转义才算合法。
					if _, paired := followingLowSurrogate(raw, bs+6); !paired {
						return fmt.Errorf("invalid Unicode surrogate in JSON string at byte offset %d: unpaired high surrogate escape \\u%04X (expected a following low surrogate escape \\uDC00-\\uDFFF)",
							bs, cp)
					}
					i = bs + 12 // 越过完整的一对转义（\uXXXX\uXXXX 共 12 字节）
				case cp >= 0xDC00 && cp <= 0xDFFF:
					// 低代理项没有前导高代理项，无法单独表示字符。
					return fmt.Errorf("invalid Unicode surrogate in JSON string at byte offset %d: unpaired low surrogate escape \\u%04X (no preceding high surrogate escape \\uD800-\\uDBFF)",
						bs, cp)
				default:
					i = bs + 6 // 越过完整的 \uXXXX 转义
				}
				continue
			}
			if c < 0x80 {
				// ASCII 字符（含未转义控制字符）原样跳过；
				// 未转义控制字符是 JSON 语法错误，由解码器报告。
				i++
				continue
			}
			// 非 ASCII 原始字节必须是一个完整合法的 UTF-8 编码。
			// DecodeRune 对非法首字节、截断序列、越界编码及 WTF-8 形式的
			// 代理码位（如 ED A0 80）都返回 RuneError 且 size==1；
			// 合法的 U+FFFD（EF BF BD）size==3，照常放行。
			_, size := utf8.DecodeRune(raw[i:])
			if size == 1 {
				return fmt.Errorf("invalid UTF-8 encoding in JSON string at byte offset %d: illegal byte 0x%02X",
					i, c)
			}
			i += size
		}
	}
	return nil
}

// hexEscape4 解析从 pos 开始的 4 个十六进制位为一个码位值；
// 位数不足或任一位不是十六进制字符时 ok 为 false。
func hexEscape4(raw []byte, pos int) (rune, bool) {
	if pos+4 > len(raw) {
		return 0, false
	}
	var value rune
	for k := 0; k < 4; k++ {
		c := raw[pos+k]
		var digit rune
		switch {
		case c >= '0' && c <= '9':
			digit = rune(c - '0')
		case c >= 'a' && c <= 'f':
			digit = rune(c-'a') + 10
		case c >= 'A' && c <= 'F':
			digit = rune(c-'A') + 10
		default:
			return 0, false
		}
		value = value<<4 | digit
	}
	return value, true
}

// followingLowSurrogate 判断从 pos 开始是否紧跟一个低代理项转义
// \uDC00–\uDFFF（恰好 6 字节：反斜杠、u、4 个十六进制位）。
func followingLowSurrogate(raw []byte, pos int) (rune, bool) {
	if pos+6 > len(raw) || raw[pos] != '\\' || raw[pos+1] != 'u' {
		return 0, false
	}
	low, ok := hexEscape4(raw, pos+2)
	if !ok || low < 0xDC00 || low > 0xDFFF {
		return 0, false
	}
	return low, true
}

