166	func runInit(args []string) {
167		cf := newCmdFlags("init")
168		balanceRaw := cf.fs.String("balance", "", "initial treasury balance (non-negative int64)")
169		cf.parse(args)
170		balance := parseIntFlag(cf.fs, "balance", *balanceRaw)
171	
172		store, err := govflow.InitTreasury(cf.state, balance)
173		if err != nil {
174			fail(err)
175		}
176		defer store.Close()
177		if cf.asJSON {
178			emitJSON(map[string]any{"state": cf.state, "treasury": balance, "initialized": true})
179			return
180		}
181		fmt.Printf("initialized %s with treasury balance %d\n", cf.state, balance)
182	}
183	
184	func runRegister(args []string) {
185		cf := newCmdFlags("register")
186		id := cf.fs.String("id", "", "proposal id (non-empty)")
187		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64)")
188		var actions actionList
189		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
190		cf.parse(args)
191		if *id == "" {
192			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
193			os.Exit(2)
194		}
195		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
196	
197		store, err := govflow.Open(cf.state)
198		if err != nil {
199			fail(err)
200		}
201		defer store.Close()
202		existed, err := store.Register(*id, timelock, []string(actions))
203		if err != nil {
204			fail(err)
205		}
206		if cf.asJSON {
207			emitJSON(map[string]any{"id": *id, "state": "passed", "timelock_end": timelock,
208				"actions": []string(actions), "already_registered": existed})
209			return
210		}
211		if existed {
212			fmt.Printf("proposal %s already registered with identical content\n", *id)
213		} else {
214			fmt.Printf("registered passed proposal %s (%d action(s), timelock_end=%d)\n", *id, len(actions), timelock)
215		}
216	}
217	
218	// memberList 收集重复的 --member ID:WEIGHT 参数，保持提交顺序。
219	type memberList []govflow.VoteMember
220	
221	func (m *memberList) String() string { return fmt.Sprint([]govflow.VoteMember(*m)) }
222	func (m *memberList) Set(v string) error {
223		id, weight, err := splitMember(v)
224		if err != nil {
225			return err
226		}
227		*m = append(*m, govflow.VoteMember{ID: id, Weight: weight})
228		return nil
229	}
