394	func runVote(args []string) {
395		cf := newCmdFlags("vote")
396		id := cf.fs.String("id", "", "proposal id to vote on")
397		voter := cf.fs.String("voter", "", "voting member (must be a final representative)")
398		choice := cf.fs.String("choice", "", "vote choice: for or against")
399		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64)")
400		cf.parse(args)
401		if *id == "" || *voter == "" {
402			fmt.Fprintf(os.Stderr, "usage error: --id and --voter are required\n")
403			os.Exit(2)
404		}
405		var support bool
406		switch *choice {
407		case "for":
408			support = true
409		case "against":
410			support = false
411		default:
412			fmt.Fprintf(os.Stderr, "usage error: --choice must be %q or %q\n", "for", "against")
413			os.Exit(2)
414		}
415		now := parseIntFlag(cf.fs, "now", *nowRaw)
416	
417		store, err := govflow.Open(cf.state)
418		if err != nil {
419			fail(err)
420		}
421		defer store.Close()
422		ballot, err := store.CastVote(*id, *voter, support, now)
423		if err != nil {
424			fail(err)
425		}
426		if cf.asJSON {
427			emitJSON(ballot)
428			return
429		}
430		fmt.Printf("recorded vote proposal=%s representative=%s choice=%s weight=%d voted_at=%d\n",
431			*id, ballot.Representative, choiceWord(ballot.Support), ballot.Weight, ballot.VotedAt)
432	}
