500	func runBalances(args []string) {
501		cf := newCmdFlags("balances")
502		account := cf.fs.String("account", "", "show only this recipient account balance (unknown accounts are 0)")
503		cf.parse(args)
504		store, err := govflow.Open(cf.state)
505		if err != nil {
506			fail(err)
507		}
508		defer store.Close()
509		// 一次快照读取保证资金库与账户余额来自同一份已提交状态，
510		// 不会把并发执行前后的数字拼在一起。
511		snapshot, err := store.BalanceSnapshot()
512		if err != nil {
513			fail(err)
514		}
515		if *account != "" {
516			// 未出现过的账户余额为 0，且不向状态文件新增账户记录。
517			balance := snapshot.Balances[*account]
518			if cf.asJSON {
519				emitJSON(map[string]any{"treasury": snapshot.Treasury, "account": *account, "balance": balance})
520			} else {
521				fmt.Printf("treasury %d\n%s %d\n", snapshot.Treasury, *account, balance)
522			}
523			return
524		}
525		if cf.asJSON {
526			emitJSON(map[string]any{"treasury": snapshot.Treasury, "balances": snapshot.Balances})
527			return
528		}
529		fmt.Printf("treasury %d\n", snapshot.Treasury)
530		accounts := make([]string, 0, len(snapshot.Balances))
531		for acct := range snapshot.Balances {
532			accounts = append(accounts, acct)
533		}
534		sort.Strings(accounts)
535		for _, acct := range accounts {
536			fmt.Printf("%s %d\n", acct, snapshot.Balances[acct])
537		}
538	}
