540	func runProposal(args []string) {
541		cf := newCmdFlags("proposal")
542		id := cf.fs.String("id", "", "proposal id")
543		cf.parse(args)
544		if *id == "" {
545			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
546			os.Exit(2)
547		}
548		store, err := govflow.Open(cf.state)
549		if err != nil {
550			fail(err)
551		}
552		defer store.Close()
553		record, ok, err := store.Proposal(*id)
554		if err != nil {
555			fail(err)
556		}
557		if ok {
558			// 保持既有 JSON 形状：直接输出登记提案记录。
559			if cf.asJSON {
560				emitJSON(record)
561				return
562			}
563			printProposalText(record)
564			return
565		}
566		voteView, vok, verr := store.VoteProposal(*id)
567		if verr != nil {
568			fail(verr)
569		}
570		if !vok {
571			fail(fmt.Errorf("%w: %s", govflow.ErrProposalNotFound, *id))
572		}
573		if cf.asJSON {
574			emitJSON(voteView)
575			return
576		}
577		printVoteProposalText(voteView)
578	}
