580	func runProposals(args []string) {
581		cf := newCmdFlags("proposals")
582		cf.parse(args)
583		store, err := govflow.Open(cf.state)
584		if err != nil {
585			fail(err)
586		}
587		defer store.Close()
588		// 一次快照读取保证登记提案与投票提案来自同一份已提交状态，
589		// 不会把并发执行前后的提案状态拼在一起。
590		snapshot, err := store.ProposalsSnapshot()
591		if err != nil {
592			fail(err)
593		}
594		registered := snapshot.Registered
595		voting := snapshot.Voting
596		if cf.asJSON {
597			// 保持既有 JSON 形状：一个数组；登记记录字段不变，投票提案带额外字段。
598			merged := make([]any, 0, len(registered)+len(voting))
599			for _, r := range registered {
600				merged = append(merged, r)
601			}
602			for _, v := range voting {
603				merged = append(merged, v)
604			}
605			emitJSON(merged)
606			return
607		}
608		for _, record := range registered {
609			printProposalText(record)
610		}
611		for _, view := range voting {
612			printVoteProposalText(view)
613		}
614	}
