664	func printProposalText(p govflow.ProposalRecord) {
665		fmt.Printf("proposal %s state=%s timelock_end=%d actions=%d\n", p.ID, p.State, p.TimelockEnd, len(p.Actions))
666		for i, action := range p.Actions {
667			fmt.Printf("  action %d: %s\n", i, action)
668		}
669	}
670	
671	func printVoteProposalText(v *govflow.VoteProposalView) {
672		fmt.Printf("proposal %s source=vote state=%s quorum=%d voting=[%d,%d) timelock_end=%d actions=%d total_weight=%d\n",
673			v.ID, v.State, v.Quorum, v.StartAt, v.Deadline, v.TimelockEnd, len(v.Actions), v.TotalWeight)
674		for _, m := range v.Members {
675			chain := strings.Join(m.Path, "->")
676			if len(m.Path) == 1 {
677				fmt.Printf("  member %s weight=%d representative=self\n", m.ID, m.Weight)
678			} else {
679				fmt.Printf("  member %s weight=%d path=%s\n", m.ID, m.Weight, chain)
680			}
681		}
682		for i, action := range v.Actions {
683			fmt.Printf("  action %d: %s\n", i, action)
684		}
685		for _, b := range v.Ballots {
686			fmt.Printf("  ballot representative=%s choice=%s weight=%d voted_at=%d\n",
687				b.Representative, choiceWord(b.Support), b.Weight, b.VotedAt)
688		}
689		if v.Tally != nil {
690			verdict := "rejected"
691			if v.Tally.Passed {
692				verdict = "passed"
693			}
694			fmt.Printf("  tally for=%d against=%d turnout=%d => %s tallied_at=%d\n",
695				v.Tally.ForWeight, v.Tally.AgainstWeight, v.Tally.Turnout, verdict, v.Tally.TalliedAt)
696		}
697	}
698	
699	func printReceiptText(r *govflow.Receipt, header bool) {
700		if header {
701			fmt.Printf("receipt proposal=%s order=%d executed_at=%d actions=%d\n", r.ProposalID, r.Order, r.ExecutedAt, len(r.Actions))
702		} else {
703			fmt.Printf("executed proposal %s at %d (%d action(s)); receipt order %d\n", r.ProposalID, r.ExecutedAt, len(r.Actions), r.Order)
704		}
705		for _, ar := range r.Actions {
706			fmt.Printf("  action %d: %s\n", ar.Index, ar.Action)
707			fmt.Printf("    treasury:  %d -> %d\n", ar.Treasury.Before, ar.Treasury.After)
708			fmt.Printf("    %s: %d -> %d\n", ar.Recipient.Account, ar.Recipient.Before, ar.Recipient.After)
709		}
710	}
711	
712	func runDemo() {
713		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
714			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
715		if err := govflow.Vote(&proposal, 700, true); err != nil {
716			fmt.Println("vote refused:", err)
717		}
718		if err := govflow.Vote(&proposal, 200, false); err != nil {
719			fmt.Println("vote refused:", err)
720		}
721		next := govflow.Tally(&proposal)
722		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
723		proposal.State = next
724		proposal.TimelockEnd = 400
725		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
726	}
