		t.Fatalf("identical retry existed=%v err=%v", existed, err)
	}
	// nil 与空切片等价。
	existed, err = store.Register("gip-empty", 0, nil)
	if err != nil || existed {
		t.Fatalf("register empty actions: %v %v", existed, err)
	}
	existed, err = store.Register("gip-empty", 0, []string{})
