func TestRegisterRejectsInvalidUTF8(t *testing.T) {
	store, path := openTempStore(t, 1000)
	defer store.Close()

	// 已有提案：编号含用户真实写出的 U+FFFD，动作含中文与表情。
	mustRegister(t, store, "gip-�", 100, "transfer:审计账户✅:50")
