	if existed, err := store.Register("gip-\xff", 100, []string{"transfer:审计账户✅:50"}); !errors.Is(err, ErrInvalidRegistration) || existed {
		t.Fatalf("rewrites-to-existing id existed=%v err=%v, want ErrInvalidRegistration", existed, err)
	}
