	if _, err := store.Register("gip-�", 100, []string{"transfer:审计账户✅:5\xff0"}); !errors.Is(err, ErrInvalidRegistration) {
		t.Fatalf("one-bad-byte action err=%v, want ErrInvalidRegistration", err)
